193	// Database reads only, memoized per request so Home can start them before its own data
194	// resolves; nothing here depends on the projection. Independent reads load together.
195	export const loadInsightEvidence = cache(async (db: SupabaseClient, workspaceId: string, currency: string, today: string) => {
196	    async function rows<T>(table: string, columns: string, start?: string): Promise<T[]> {
197	      const collected: T[] = [];
198	      for (let offset = 0; offset <= 10000; offset += 500) {
199	        let query = db.from(table).select(columns).eq("workspace_id", workspaceId);
200	        if (start) query = query.gte("posted_on", start).lte("posted_on", today);
201	        const result = await query.order(table === "insight_dismissals" ? "evidence_key" : "id").range(offset, offset + 499);
202	        if (result.error) throw result.error;
203	        if (offset === 10000 && result.data.length) throw new Error("Insight evidence exceeds the supported 10,000-row limit");
204	        collected.push(...result.data as T[]);
205	        if (result.data.length < 500) return collected;
206	      }
207	      return collected;
208	    }
209	    async function byIds<T>(columns: string, ids: string[]) {
210	      const pages = await Promise.all(Array.from({ length: Math.ceil(ids.length / 100) }, async (_, index) => {
211	        const page = await db.from("transactions").select(columns).eq("workspace_id", workspaceId).in("id", ids.slice(index * 100, index * 100 + 100));
212	        if (page.error) throw page.error;
213	        return page.data as unknown as T[];
214	      }));
215	      return pages.flat();
216	    }
217	    const recentStart = new Date(Date.parse(`${today}T00:00:00Z`) - 90 * 86400000).toISOString().slice(0, 10);
218	    const columns = "id,parent_transaction_id,account_id,description,amount_minor::text,currency_code,status,kind,review_reasons,posted_on,category_id,merchant_id,refund_of_id";
219	    const canonicalColumns = columns.replace("parent_transaction_id,", "");
220	    const [pref, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata] = await Promise.all([
221	      db.from("insight_preferences").select("important_only,minimum_change_minor::text,currency_code,upcoming_days,max_items").eq("workspace_id", workspaceId).maybeSingle(),
222	      rows<Budget>("spending_plans", "id,category_id,currency_code,limit_minor::text,enabled,rollover,rollover_from"), rows<{ id: string; name: string }>("categories", "id,name"),
223	      rows<Goal>("goals", "id,name,target_minor::text,recorded_saved_minor::text,saved_as_of,status"),
224	      rows<Recurring>("recurring_series", "id,label,evidence_invalidated,evidence_baseline,invalidated_assumption_version"),
225	      rows<MonthlyLimit & { id: string; plan_id: string }>("spending_plan_limits", "id,plan_id,effective_month,limit_minor::text,enabled,version"),
226	      rows<{ evidence_key: string }>("insight_dismissals", "evidence_key"),
227	      rows<ReviewTransaction & { account_id: string }>("transactions", canonicalColumns, recentStart),
228	      loadSourceCoverageMetadata(db, workspaceId, true),
229	    ]);
230	    if (pref.error) throw pref.error;
231	    const preferences = insightPreferencesSchema.parse(pref.data ?? defaultInsightPreferences(currency));
232	    const first = budgets.filter(budget => budget.enabled && budget.rollover).reduce((start, budget) => budget.rollover_from < start ? budget.rollover_from : start, recentStart);
233	    const recurringEvidence = new Map(canonical.map(row => [row.id, row]));
234	    const missingBaselineIds = [...new Set(recurring.flatMap(series => (series.evidence_baseline ?? []).map(row => row.id)))].filter(id => !recurringEvidence.has(id));
235	    if (missingBaselineIds.length > 10000) throw new Error("Recurring insight evidence exceeds the current bound");
236	    const [transactions, older] = await Promise.all([
237	      rows<ReviewTransaction & { account_id: string }>("effective_transactions", columns, first),
238	      byIds<ReviewTransaction & { account_id: string }>(canonicalColumns, missingBaselineIds),
239	    ]);
240	    for (const row of older) recurringEvidence.set(row.id, row);
241	    const refundIds = [...new Set(transactions.flatMap(row => row.refund_of_id ? [row.refund_of_id] : []))];
242	    const originals = await byIds<{ id: string; category_id: string | null }>("id,category_id", refundIds);
243	    for (const row of transactions) if (row.refund_of_id) row.refund_category_id = originals.find(original => original.id === row.refund_of_id)?.category_id ?? row.refund_category_id;
244	    return { preferences, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata, first, transactions, recurringEvidence };
245	});
