247	async function loadInsights({ db, workspaceId, currency, today, settings, projection, missingInputs, names, wealth }: InsightPanelProps) {
248	    const { preferences, budgets, categories, goals, recurring, limits, dismissals, canonical, sourceMetadata, first, transactions, recurringEvidence } = await loadInsightEvidence(db, workspaceId, currency, today);
249	    const sourceCoverage = buildSourceCoverage({ from: first, to: today }, transactions, sourceMetadata?.imports, sourceMetadata?.sources);
250	    const warnings = describeMissingInputs([...missingInputs, ...(projection.input.missingInputs ?? [])], names);
251	    if (transactions.some(row => row.status === "posted" && row.review_reasons?.length)) warnings.push("Some financial classifications need review; comparisons omit uncertain rows");
252	    const spendingRows = transactions.map(row => ({ amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code, status: row.status, kind: row.kind, reviewReasons: row.review_reasons, postedOn: row.posted_on, categoryId: row.category_id,
253	      ...(row.refund_of_id ? { refundOfCategoryId: row.refund_category_id ?? null } : {}) }));
254	    const budgetEvidence: InsightInput["budgets"] = [];
255	    for (const budget of budgets.filter(budget => budget.enabled)) {
256	      const budgetCoverage = buildSourceCoverage({ from: budget.rollover ? budget.rollover_from : `${today.slice(0, 7)}-01`, to: today, currencyCode: budget.currency_code }, transactions, sourceMetadata?.imports, sourceMetadata?.sources);
257	      const progress = budgetProgress(spendingRows, budget.category_id, budget.currency_code, today.slice(0, 7), BigInt(budget.limit_minor), budget.rollover ? { startsMonth: budget.rollover_from.slice(0, 7), history: limits.filter(limit => limit.plan_id === budget.id) } : undefined, budgetCoverage);
258	      if (progress.allowanceMinor === null) { if (progress.limitation) warnings.push(progress.limitation); continue; }
259	      budgetEvidence.push({ id: budget.id, name: categories.find(category => category.id === budget.category_id)?.name ?? "Category", currency: budget.currency_code,
260	        spentMinor: progress.spentMinor.toString(), allowanceMinor: progress.allowanceMinor.toString(), partial: progress.partial, sourceCoverage: budgetCoverage });
261	    }
262	    const events = projection.input.events.filter(event => event.source !== "estimated" && event.expectedMinor < 0n);
263	    const obligations = new Map<string, InsightInput["obligations"][number]>();
264	    for (const event of events) {
265	      const id = `${event.accountId}:${event.date}`, previous = obligations.get(id);
266	      obligations.set(id, { id, name: "Confirmed payments", date: event.date, amountMinor: ((previous ? BigInt(previous.amountMinor) : 0n) + event.expectedMinor).toString(), currency });
267	    }
268	    const insights = buildInsights({ today, currency, locale: settings.locale, transactions, canonicalTransactions: canonical, categories, budgets: budgetEvidence, sourceCoverage, forecastSourceCoverage: projection.sourceCoverage,
269	      recurring: recurring.map(series => ({ ...series, evidence: [series.invalidated_assumption_version, series.evidence_baseline, (series.evidence_baseline ?? []).map(row => recurringEvidence.get(row.id) ?? null)] })),
270	      obligations: [...obligations.values()],
271	      goals: goals.filter(goal => goal.status === "active").map(goal => ({ id: goal.id, name: goal.name, targetMinor: goal.target_minor, savedMinor: goal.recorded_saved_minor, savedAsOf: goal.saved_as_of })),
272	      wealth: wealth.filter(item => !item.removed_at).map(item => ({ id: item.id, name: item.name, kind: item.kind, amountMinor: item.amount_minor, currency: item.currency_code, asOf: item.as_of })),
273	      missingInputs: warnings, available: projection.available.status === "available" ? { amountMinor: projection.available.amountMinor.toString(), limitingDate: projection.available.limitingDate } : null,
274	    }, preferences, settings.muted_insight_types, dismissals.map(dismissal => dismissal.evidence_key));
275	    return insights;
