import re
def add(var, currency, indent):
    lines = [f'await page.goto("/money/accounts");',
             'const adder = page.locator("details").filter({ has: page.locator("summary", { hasText: "Add account" }) });',
             'await adder.locator("summary").click();',
             f'await adder.getByLabel("Name", {{ exact: true }}).fill({var});']
    if currency: lines.append(f'await adder.getByLabel("Currency", {{ exact: true }}).fill({currency});')
    lines.append('await adder.getByRole("button", { name: "Add account", exact: true }).click();')
    return "\n".join(indent + line for line in lines) + "\n"

def edit(path, old, new):
    s = open(path).read()
    assert old in s, (path, old[:60])
    open(path, 'w').write(s.replace(old, new))

